-- PAPER-LEARN-PROBATION-SETTLE-1 part 1 of 9 (2026-11-05, charter pillar autonomy, program QNFO.OPS; cluster C8-PROJECTS-GOALS of the roadmap and backlog completion sweep).
-- Settles 25 probationary direct paper learnings (ids 4688 to 4799 of the 225 read on 2026-11-04 23:00Z): each row was read in full (claim, lever, application and the model's apply signal) against the live fleet and given one disposition with its reason.
-- PAPER-LEARN-TRIAGE-1 parked them in probation because its catalogue held 6 mechanisms; the apply signal usually meant the model did not know the fleet already does this. Dispositions: already-in-place (mechanism named, existence read today), rejected (category and specific reason, with what would justify re-proposing), routed (to agent_issues 1000459 TRIGGER-FLAP-1 or goal external-impact-per-dollar).
-- Each goal PAPER-LEARN-<id> (DoD: the learning is settled) then completes on its next probe, and roadmap row GL-PAPER-LEARN-<id> verifies in the hourly loop. Revert one row: UPDATE paper_learnings SET fleet_status = 'probation' WHERE id = <id>.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: UPDATE paper_learnings SET fleet_status = (SELECT b.fleet_status FROM bak_20261105_c8_pl_01 b WHERE b.id = paper_learnings.id), status_note = (SELECT b.status_note FROM bak_20261105_c8_pl_01 b WHERE b.id = paper_learnings.id), updated_at = (SELECT b.updated_at FROM bak_20261105_c8_pl_01 b WHERE b.id = paper_learnings.id) WHERE id IN (SELECT id FROM bak_20261105_c8_pl_01)

CREATE TABLE IF NOT EXISTS bak_20261105_c8_pl_01 AS SELECT * FROM paper_learnings WHERE id IN (4688, 4706, 4707, 4719, 4736, 4742, 4747, 4748, 4759, 4764, 4765, 4768, 4769, 4783, 4784, 4785, 4786, 4787, 4788, 4789, 4794, 4795, 4796, 4797, 4799);

UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; no-measured-gap): The claim is the paper''s warning to its own designers that a PLAUSIBLE verdict is not a feasibility guarantee. Fleet changes already state a prediction (metric, direction, size) before they merge and the review gate reads risky diffs; no auto-merged change with an unstated budget assumption is shown. Re-propose with a merged PR whose cost claim failed on an unstated assumption.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 4688 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; guard): Metric definitions are protected against count-inflation twice: proxy measures are labelled proxy and never targets, and a target metric that improves while a guard metric worsens is a regression.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 4706 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; analogy-only): The 97.2 percent and p_bridge anchor is a vocabulary statistic of one text corpus. Fleet thresholds in analytics_metric_triggers are set from fleet measurements, and nothing wires a literature constant into a trigger. Re-propose with a trigger whose threshold was copied from outside data.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 4707 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; no-measured-gap): Union-bound allocation of a combined error budget across k independent probes: the fleet closes an issue on one contract probe, and a relapse reopens it (issue_refile_reopen), so there is no k-of-k close policy to allocate across. Re-propose if a close policy that needs several probes is introduced.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 4719 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; merge): Checks already run inside the merge path, before and right after the deploy, not in a post-merge sweep: PR-FAST-GUARDS-1, the REVIEW-GATE-1 read of risky diffs and the DEPLOY-PROBES-1 canary revert.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 4736 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; registry): One row per metric holds one formula and a required source_of_truth, so two divergent definitions of the same metric cannot be registered under one key; the convention is documented in the row.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 4742 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; no-measured-gap): 1-(1-p)^G is the paper''s decoherence algebra. The fleet reads end-to-end reliability directly (code_task_success_rate_30d 0.52, remedy_efficacy_30d 0.53, session_execution_ratio_30d 0.81 read 2026-11-04) rather than composing per-stage probabilities. Re-propose with per-stage failure rates whose product disagrees with the measured end-to-end rate.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 4747 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; no-measured-gap): Summing per-loop degradation rates re-derives a number the registry already reads off the whole fleet (metrics_in_breach 95 at 2026-11-04T22:02Z, per-class SLAs); no fleet breach is shown that per-loop thresholds missed and a sum would have caught. Re-propose with such a breach.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 4748 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; pred): A projection is separated from a measurement by the prediction record: the predicted outcome is logged before the change and compared with the re-measured value after (outcome_matched), which is the learning''s own remedy (benchmark, then compare actual with projected).', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 4759 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; conflicts): Conflicts with METRIC-CLOSED-LOOP-1 as written in CLAUDE.md: a metric is registered together with its trigger or a named exemption, so binding-ness is decided at registration, not by a runtime arming rule. The noise the learning fears is measured and owned in TRIGGER-FLAP-1 (agent_issues 1000459, open).', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 4764 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; newloop): A new worker must declare what must still work after deploy (probes.json or probes: none with a reason, checked in the PR by deploy_probes.py --check-pr) and a recurring operation is registered with the D1 query that proves it ran, so a new loop is instrumented before it carries load.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 4765 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; no-measured-gap): An all-confirmed record being suspect is the paper''s note on its own forecast register. The trust ledger widens only fleet loop scopes from verified outcomes and no case is shown of a loop that gamed it with unfalsifiable claims; the 0.26 prediction miss rate (read 2026-11-04) shows the records are not all-confirmed. Re-propose with a loop whose perfect record later proved gamed.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 4768 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; ens): Same-model cross-checks are already treated as correlated: the ensemble policy requires disjoint model families and the review gate reads a risky diff with two disjoint families before merge.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 4769 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; pred,birth): Pre-registration exists: the predicted outcome is written before the change (decision_log.predicted_outcome, prediction_logged_share_7d 0.983) and every issue is born with its closing probe before any fix (519 open issues, 0 without a contract).', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 4783 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; birth): Every issue is born with a closing probe that states in advance the observation which closes it, and a failed probe keeps it open; the refutation record is remedy_efficacy_30d.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 4784 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; no-measured-gap): The ledger already scores predicted against matched outcomes (decision_log.outcome_matched, prediction_miss_rate_7d 0.26). A per-loop Bayesian delta-log-odds needs a likelihood model the fleet does not have, and no misjudged trust widening is shown. Re-propose with a loop whose trust was widened on retrodicted success.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 4785 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; ens): Agreement among members that share error sources is already discounted: ENSEMBLE-POLICY-1 states that a 9-judge, 7-family panel is worth about 2.2 votes and requires disjoint families, few and small.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 4786 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; no-measured-gap): Capping doctrine amendments per cycle would add a limit to an owner-governed document that changes by pull request with a version bump; no measured case of a doctrine amended to absorb a failure without predicting anything is shown. Re-propose with such a case.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 4787 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; no-measured-gap): Fluctuation-driven false positives are measured and owned in TRIGGER-FLAP-1 (agent_issues 1000459, 167 reopens on 44 tickets) which fixes them with a band; a scan-count log with multiplicity correction would sit on top of that band with no false-positive rate of its own. Re-propose with the share left after TRIGGER-FLAP-1 lands.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 4788 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; maxatt): A fixed observation budget before escalation exists: remediation_contracts.max_attempts bounds probe re-runs and an over-retried contract is parked as escalated instead of being sampled again.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 4789 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; modeleval,guard): An improvement claim is tested against the existing alternative, not the loop''s own earlier output: qnfo-model-eval benchmarks a candidate against the production control model, and the fleet reads the same items a week apart instead of a pool mean (OUTPUT-QUALITY-LEDGER-1).', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 4794 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'routed', status_note = 'PL-TRIAGE-2 routed (c8-projects-goals session, 2026-11-05; goal-cost): Routed to goal external-impact-per-dollar (qnfo-fleet-control, adopted, program QNFO.OPS), the standing goal for a unified cost measured per outcome (v_cost_all_in already holds the all-vendor cost); this learning adds cost per completed task as the unit. Tracked there with a machine check written by the 2026-11-05 roadmap sweep.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 4795 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'already-in-place', status_note = 'PL-TRIAGE-2 in place (c8-projects-goals session, 2026-11-05; modeleval): The boring baseline runs first: qnfo-model-eval benchmarks cheaper models against the production control model on a fixed battery with automatic revert, and BUDGET-SOFT-ROUTE-1 steers to the cheapest capable model.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 4796 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'routed', status_note = 'PL-TRIAGE-2 routed (c8-projects-goals session, 2026-11-05; trigger-flap): Routed to agent_issues 1000459 (TRIGGER-FLAP-1, open, critical, qnfo-fleet-control): a count that scatters around its mean needs a band and a minimum observation count, not a bare threshold; the claim (a trigger on 55 observations is noise) is the same defect.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 4797 AND fleet_status = 'probation';
UPDATE paper_learnings SET fleet_status = 'rejected', status_note = 'PL-TRIAGE-2 rejected (c8-projects-goals session, 2026-11-05; no-measured-gap): Fleet cost comparisons come from measured ledgers (cost_daily, v_cost_all_in), not TDP assumptions; a conservative upper bound on a cheap path is the paper''s CPU power choice. Re-propose with a fleet budget comparison that failed for a missing worst case.', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now') WHERE id = 4799 AND fleet_status = 'probation';
